script.text:
function load$GridReport$(g) {
	g.add_onRender(on$GridReport$Render);
	g.add_commandEvent(on$GridReport$ExecuteCommand);
	g.add_onResponseComplete(on$GridReport$ResponseComplete);
	var fcFields = g._fields.map(function(e) {return e.Name}).filter(function(e) {return e.includes('_nt')});
	var dcFields = fcFields.map(function(e) {return e.replace('_nt', '')}).join(',');
	fcFields = fcFields.join(',')
	g._hiddenFields = [
			{Fields: fcFields, Value: false},
			{Fields: dcFields, Value: false}
	];
	g._$c = g._getColumnOrder('ma_so');
	g._$systotal = g._getColumnOrder('systotal');
	g._arrayIndex = [];
	var arrayCol = ['t_th_nt', 't_th', 'tra_lk', 'tra_lk_nt', 'tra_ky', 'tra_ky_nt'];
	for (var i = 0; i < arrayCol.length; i++) {g._arrayIndex.push(g._getColumnOrder(arrayCol[i]))}

}
function dispose$GridReport$(g) {
	try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}; 
	try {g.remove_commandEvent(on$GridReport$ExecuteCommand);} catch (ex) {};
	try {g.remove_onResponseComplete(on$GridReport$ResponseComplete);} catch (ex) {};
}
function on$GridReport$Render(sender, eventArgs) {		
	var g = eventArgs.grid;  
	//'form, mau_bc, ma_dvcs, thang, nam, ma_vv'
	var v = g._queryFilterString.split(String.fromCharCode('253'))[2];
	Array.from(g._gridTable.rows).forEach(function(e) {
		var tds = Array.from(e.children);
		g._arrayIndex.forEach(function(i) {
			tds[i].firstChild.firstChild.style.color = '#4e81f0';
		})
	})
	g._hiddenFields = g._hiddenFields.map(function(e, i) {
		e.Value = (i==v);
		return e
	})	
	if (g._hiddenFields) {
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}
}
/* </flatten> */
function on$GridReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'View':
			e.type.cancelEvent = true;
			var typeCol, index, systotal, val;
			index = g._arrayIndex.indexOf(g._activeColumn);
			systotal = g._getItemValue(g._activeRow, g._$systotal);
			val = g._getItemValue(g._activeRow, g._activeColumn);
			var ma_kh = g._getItemValue(g._activeRow, g._getColumnOrder('ma_kh'));
			if (index == -1 || systotal != 1 || val == 0) break;
			switch (index) {
				case 0:
				case 1:
					typeCol = 1;
					break;
				case 2:
				case 3:
					typeCol = 2;
					break;
				case 4:
				case 5:
					typeCol = 3;
					break;
				case 6:
				case 7:
					typeCol = 4;
					break;
				default:
					break;
			}
			var code = g._getItemValue(g._activeRow, g._$c);
			var a = g._queryFilterString.split(String.fromCharCode(253));
			g.request(g, 'ViewDetail', 'ViewDetail', [['form', 'String', a[1]], ['ma_so', 'String', code], ['ky', 'Decimal', a[4]], ['nam', 'Decimal', a[5]], ['cot_dl', 'Decimal', typeCol], ['ma_vv', 'String', a[6]], ['ma_kh', 'String', ma_kh ]);
			break;
		default:
			break;
	}
}

function on$GridReport$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case 'ViewDetail':
			g._$result = result;
			g._navigate(g._activeCell, '&Url;');
			break;
		default:
			break;
	}
}
/* <flatten type="Javascript"> */
function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		var l = g._getColumnOrder($func.trim(a[i]));
		if (l != -1) g._setColumnVisible(l, !v);
	}
}
function beforeDrillDown(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));}
function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}
function passQueryParameters(g) {&Parameter;
	var q = g._queryFilterString.split(String.fromCharCode(253)), fc = ((q[2] == '0') ? '10' : '20');

	var a = [
		{Name: 'tk_no', Value: g._$result[0].Value},
		{Name: 'tk_co', Value: g._$result[1].Value},
		{Name: 'tk_0gt', Value: g._$result[2].Value},
		{Name: 'date_from', Value: g._$result[3].Value},
		{Name: 'date_to', Value: g._$result[4].Value},
		{Name: 'nh_vv1', Value: g._$result[5].Value},
		{Name: 'ds_ma_phi', Value: g._$result[6].Value},
		{Name: 'ma_hd', Value: g._getItemValue(g._activeRow, g._getColumnOrder('ma_hd')),
		{Name: 'ma_dvcs', Value: q[3]},
		{Name: 'mau_bc', Value: fc}
	];
	var session = {Memvar: a, Script: 'this._convection = true;'&Session;};
	console.log(a);
	g._passParameter(session);
}
